<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Mount Fuji, Chureito Pagoda, Sakura - Dusk</title>
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#1a1626}
  #c{display:block;width:100%;height:100%}
</style>
<script type="importmap">
{ "imports": { "three": "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js" } }
</script>
</head>
<body>
<canvas id="c"></canvas>
<script type="module">
import * as THREE from 'three';

// ---------- renderer / scene / camera ----------
const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('c'), antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(42, innerWidth/innerHeight, 0.1, 4000);
camera.position.set(0, 44, 175);
camera.lookAt(0, 46, 0);

scene.fog = new THREE.Fog(0x3a2b52, 220, 1600);

// ---------- sky: procedural gradient dome ----------
const skyGeo = new THREE.SphereGeometry(2500, 32, 20);
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false,
  uniforms: { top: { value: new THREE.Color(0x1b1b3a) }, mid: { value: new THREE.Color(0x6a3d6e) }, bot: { value: new THREE.Color(0xe8875a) } },
  vertexShader: `varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
  fragmentShader: `
    uniform vec3 top, mid, bot; varying vec3 vP;
    void main(){
      float h = normalize(vP).y;
      vec3 c = h > 0.0 ? mix(mid, top, pow(h, 0.7)) : mix(mid, bot, pow(-h, 0.8));
      // dusk glow band near horizon in front of Fuji
      float glow = exp(-pow(max(h,0.0)*4.0, 2.0));
      c += vec3(0.9,0.45,0.2) * glow * 0.35;
      gl_FragColor = vec4(c, 1.0);
    }`
});
scene.add(new THREE.Mesh(skyGeo, skyMat));

// stars (upper sky)
{
  const n = 400, pos = new Float32Array(n*3);
  for (let i=0;i<n;i++){
    const v = new THREE.Vector3().randomDirection();
    v.y = Math.abs(v.y)*0.9 + 0.25;
    v.multiplyScalar(2200);
    pos.set([v.x,v.y,v.z], i*3);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos,3));
  scene.add(new THREE.Points(g, new THREE.PointsMaterial({ color: 0xffffff, size: 4, sizeAttenuation: false, transparent: true, opacity: 0.7 })));
}

// ---------- lights ----------
scene.add(new THREE.HemisphereLight(0xa98cc9, 0x3a2c44, 1.4));
const sun = new THREE.DirectionalLight(0xffb070, 2.2);
sun.position.set(-400, 160, 700);
scene.add(sun);
const fill = new THREE.DirectionalLight(0x7788cc, 0.7);
fill.position.set(300, 200, -400);
scene.add(fill);

// ---------- materials (flat low-poly look) ----------
const mat = (c, extra={}) => new THREE.MeshLambertMaterial({ color: c, flatShading: true, ...extra });

const M = {
  snow: mat(0xf3ecf5),
  rock: mat(0x4d5a80),
  rockDark: mat(0x3c4870),
  hill: mat(0x33455f),
  ground: mat(0x2b3a52),
  pagRed: mat(0xc0392b),
  pagDark: mat(0x8e2b20),
  roof: mat(0x5a3d5c),
  white: mat(0xe8e0e0),
  trunk: mat(0x4a2e2a),
  blossom: mat(0xf5b8cd),
  blossom2: mat(0xefa3bd),
};

// ---------- Mount Fuji ----------
{
  // wide stratified cone with craters
  const g = new THREE.ConeGeometry(520, 340, 14, 5);
  const p = g.attributes.position;
  for (let i=0;i<p.count;i++){
    const x=p.getX(i), y=p.getY(i), z=p.getZ(i);
    if (Math.abs(y) > 168 && y > 0){ // flatten a bit -> crater dip
      p.setY(i, 170 - (y-170)*0.15);
    }
    const r = Math.hypot(x,z);
    if (r > 1){ // rocky ridges
      const a = Math.atan2(z,x);
      const ridge = 1 + 0.045*Math.sin(a*7) + 0.03*Math.sin(a*13+2);
      p.setX(i, x*ridge); p.setZ(i, z*ridge);
    }
  }
  g.computeVertexNormals();
  const fuji = new THREE.Mesh(g, M.snow);
  fuji.position.set(-40, 170, -620);
  scene.add(fuji);

  // haze layer at Fuji base
  const haze = new THREE.Mesh(
    new THREE.SphereGeometry(700, 24, 12, 0, Math.PI*2, Math.PI*0.48, Math.PI*0.14),

